<script setup lang="ts">
import {computed,inject,nextTick,onBeforeUnmount,onMounted,ref} from 'vue';
import {adminSessionKey} from './adminSession';
import {enterAdminPortal} from './adminPortalEntry';
import {ApiError,refreshSession,userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail,paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions,billingGetGetApiV1AdminBillingApiUsersOwnerIdMediaPrices,billingSavePutApiV1AdminBillingApiUsersOwnerIdMediaPrices,billingAuditGetApiV1AdminBillingApiUsersOwnerIdMediaPricesAudit,billingEntriesGetApiV1BillingWalletsKeyIdLedger,billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments,paymentAdminHistoryGetApiV1AdminPaymentsRecharges,billingListGetApiV1AdminBillingConsumptions,userStatusPatchApiV1AdminUsersIdStatus,type RequestBillingDomainPricingMediaPrice as Price} from './api';
import PromoterIcon from './PromoterIcon.vue';
import AmountAdjustment from './AmountAdjustment.vue';
import ApiClientPrices from './ApiClientPrices.vue';
const props=defineProps<{userId:string}>(),emit=defineEmits<{changed:[]}>();
const session=inject(adminSessionKey),primary=computed(()=>session?.currentAdmin.value?.role==='ADMIN'&&session.currentAdmin.value.primary===true);
const detail=ref<Awaited<ReturnType<typeof userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail>>['data']|null>(null),options=ref<Awaited<ReturnType<typeof paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions>>['data']|null>(null),pricing=ref<Awaited<ReturnType<typeof billingGetGetApiV1AdminBillingApiUsersOwnerIdMediaPrices>>['data']|null>(null);
const prices=ref<Price[]>([]),priceEditor=ref<InstanceType<typeof ApiClientPrices>>(),pricePending=ref<Parameters<typeof billingSavePutApiV1AdminBillingApiUsersOwnerIdMediaPrices>[1]|null>(null),priceBusy=ref(false),priceReady=ref(false),priceError=ref(''),priceConflict=ref(false),busy=ref(false),error=ref(''),copied=ref(false),entering=ref(false),acting=ref(false);
const tabs=[['recharges','充值记录'],['pricing','额度与价格'],['usage','使用数据'],['logs','操作日志']] as const;
const tab=ref('pricing'),offset=ref(0),recordBusy=ref(false),recordError=ref(''),recordTotal=ref(0),quotaHistory=ref(false);
const recharges=ref<Awaited<ReturnType<typeof paymentAdminHistoryGetApiV1AdminPaymentsRecharges>>['data']>([]),ledger=ref<Awaited<ReturnType<typeof billingEntriesGetApiV1BillingWalletsKeyIdLedger>>['data']>([]),debits=ref<Awaited<ReturnType<typeof billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments>>['data']>([]),priceAudit=ref<Awaited<ReturnType<typeof billingAuditGetApiV1AdminBillingApiUsersOwnerIdMediaPricesAudit>>['data']>([]),usage=ref<NonNullable<Awaited<ReturnType<typeof billingListGetApiV1AdminBillingConsumptions>>['data']['items']>>([]);
let alive=true,version=0,recordVersion=0,priceStorage='';
const yuan=(value:string|null|undefined)=>{if(value==null)return '—';const[w,f='']=value.split('.');return `${w!.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${f.padEnd(2,'0').slice(0,2)}`;};
const date=(value:string|null|undefined)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const rechargeStatus=(row:typeof recharges.value[number])=>row.fulfilled?'已到账':({REVIEW_PENDING:'待审核',PAID:'入账中',REJECTED:'已拒绝',PENDING:'待支付',EXPIRED:'已过期',REFUNDED:'已退款',REFUND_PENDING:'退款中'}[row.status||'']||row.status||'—');
const logs=computed(()=>[...debits.value.map(row=>({id:row.requestId,time:row.recordedAt,actor:row.operatorId,action:`减少额度 ¥ ${yuan(row.amount4)}`,remark:row.remark})),...priceAudit.value.map(row=>({id:row.requestId,time:row.changedAt,actor:row.operatorId,action:'修改客户价格',remark:row.prices?.length?`${row.prices.length} 项专属价格`:'恢复默认价格'})),...recharges.value.filter(row=>row.source==='MANUAL'||row.source==='CORPORATE').map(row=>({id:row.orderId,time:row.createdAt,actor:row.submittedBy,action:`充值 ¥ ${yuan(row.amount4)} · ${rechargeStatus(row)}`,remark:row.remark}))].sort((a,b)=>String(b.time).localeCompare(String(a.time))));
function rememberPrice(){if(!priceStorage)return;try{if(pricePending.value)sessionStorage.setItem(priceStorage,JSON.stringify(pricePending.value));else sessionStorage.removeItem(priceStorage);}catch{/* Uncertain price requests remain in memory for exact retry. */}}
async function loadPrices(){priceError.value='';try{const result=await billingGetGetApiV1AdminBillingApiUsersOwnerIdMediaPrices(props.userId);if(!alive)return;pricing.value=result.data;if(!pricePending.value)prices.value=(result.data.overrides||[]).map(p=>({...p}));priceConflict.value=false;}catch{if(alive){pricing.value=null;priceError.value='价格读取失败，请重试。';}}}
async function reload(){const request=++version;busy.value=true;error.value='';try{const result=await userDirectoryDetailGetApiV1AdminUsersIdDirectoryDetail(props.userId);if(!alive||request!==version)return;if(result.data.user?.id!==props.userId||result.data.user.accountType!=='API')throw Error();detail.value=result.data;const account=await paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions({userId:props.userId});if(!alive||request!==version)return;if(account.data.userId!==props.userId||account.data.accountType!=='API')throw Error();options.value=account.data;await loadPrices();if(tab.value!=='pricing'||quotaHistory.value)await loadRecords();}catch{if(alive&&request===version){detail.value=null;options.value=null;error.value='无法读取 API 客户详情，请重试。';}}finally{if(alive&&request===version)busy.value=false;}}
async function initializePrices(){if(!primary.value)return;try{const auth=await refreshSession();if(!auth.authenticated||!auth.user?.id)throw Error();priceStorage=`xzwl-api-prices:${auth.user.id}:${props.userId}`;const saved=JSON.parse(sessionStorage.getItem(priceStorage)||'null');if(saved){if(typeof saved.requestId!=='string'||typeof saved.expectedVersion!=='number'||!Array.isArray(saved.prices))throw Error();pricePending.value=saved;prices.value=saved.prices;}priceReady.value=true;}catch{priceError.value='无法恢复此前的价格修改，请重新打开详情后重试。';}}
async function savePrices(){if(!primary.value||!priceReady.value||priceBusy.value||!pricing.value||priceConflict.value||(!pricePending.value&&!priceEditor.value?.valid))return;const wasRetry=!!pricePending.value;priceBusy.value=true;priceError.value='';if(!pricePending.value){pricePending.value={requestId:crypto.randomUUID(),expectedVersion:pricing.value.version,prices:prices.value.map(p=>({...p}))};rememberPrice();}const retry=pricePending.value;
 try{const result=await billingSavePutApiV1AdminBillingApiUsersOwnerIdMediaPrices(props.userId,retry);if(!alive)return;pricePending.value=null;rememberPrice();pricing.value=result.data;prices.value=(result.data.overrides||[]).map(p=>({...p}));}
 catch(cause){if(alive){if(cause instanceof ApiError&&([400,422].includes(cause.status)||!wasRetry&&[403,409].includes(cause.status))){pricePending.value=null;rememberPrice();priceConflict.value=cause.status===409;priceError.value=priceConflict.value?'价格已被修改，请重新读取后核对。':'价格未保存，请检查输入与权限。';}else priceError.value='价格保存结果尚未确认，请重试原请求。';}}
 finally{if(alive)priceBusy.value=false;}}
async function loadRecords(){const request=++recordVersion,selected=tab.value;recordBusy.value=true;recordError.value='';try{if(quotaHistory.value){const result=await billingEntriesGetApiV1BillingWalletsKeyIdLedger(detail.value!.user!.keyId!,{limit:100});if(alive&&request===recordVersion){ledger.value=result.data;recordTotal.value=result.data.length;}}
 else if(selected==='recharges'){const result=await paymentAdminHistoryGetApiV1AdminPaymentsRecharges({userId:props.userId});if(alive&&request===recordVersion){recharges.value=result.data;recordTotal.value=result.data.length;}}
 else if(selected==='usage'){const result=await billingListGetApiV1AdminBillingConsumptions({userId:props.userId,to:new Date().toISOString(),offset:offset.value,limit:10});if(alive&&request===recordVersion){usage.value=result.data.items||[];recordTotal.value=result.data.total;}}
 else if(selected==='logs'){const [audit,history,recharge]=await Promise.all([detail.value?.user?.keyId?billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments(detail.value.user.keyId):Promise.resolve({data:[]}),billingAuditGetApiV1AdminBillingApiUsersOwnerIdMediaPricesAudit(props.userId),paymentAdminHistoryGetApiV1AdminPaymentsRecharges({userId:props.userId})]);if(alive&&request===recordVersion){debits.value=audit.data;priceAudit.value=history.data;recharges.value=recharge.data;recordTotal.value=logs.value.length;}}
 }catch{if(alive&&request===recordVersion)recordError.value='记录读取失败，请重试。';}finally{if(alive&&request===recordVersion)recordBusy.value=false;}}
function selectTab(value:string){tab.value=value;quotaHistory.value=false;offset.value=0;recordTotal.value=0;recordVersion++;if(value!=='pricing')void loadRecords();}
async function tabKey(event:KeyboardEvent){const index=tabs.findIndex(([id])=>id===tab.value),next=event.key==='ArrowRight'?(index+1)%tabs.length:event.key==='ArrowLeft'?(index+tabs.length-1)%tabs.length:event.key==='Home'?0:event.key==='End'?tabs.length-1:null;if(next===null)return;event.preventDefault();selectTab(tabs[next]![0]);await nextTick();document.getElementById(`api-tab-${tab.value}`)?.focus();}
async function showQuotaHistory(){quotaHistory.value=true;offset.value=0;await loadRecords();}
async function copyPhone(){if(!detail.value?.user?.phone)return;try{await navigator.clipboard.writeText(detail.value.user.phone);if(alive)copied.value=true;}catch{if(alive)error.value='复制失败，请重试。';}}
async function enter(){if(!primary.value||!detail.value?.user?.enabled||entering.value)return;entering.value=true;try{await enterAdminPortal(props.userId,'api-user');}catch{if(alive)error.value='无法进入 API 后台，请重试。';}finally{if(alive)entering.value=false;}}
async function toggle(){if(!detail.value?.user||acting.value)return;acting.value=true;try{await userStatusPatchApiV1AdminUsersIdStatus(props.userId,{enabled:!detail.value.user.enabled});if(alive)emit('changed');}catch{if(alive)error.value='客户状态更新失败，请重试。';}finally{if(alive)acting.value=false;}}
function page(n:number){offset.value=n;if(tab.value==='usage'&&!quotaHistory.value)void loadRecords();}
onMounted(()=>{void (async()=>{await initializePrices();await reload();})();});
onBeforeUnmount(()=>{alive=false;version++;recordVersion++;});defineExpose({reload});
</script>
<template><div class="api-client-detail"><p v-if="error" role="alert">{{error}} <button type="button" @click="reload">重试</button></p><p v-if="busy&&!detail" role="status">正在读取客户详情…</p><template v-if="detail?.user"><section class="api-client-profile"><span class="profile-avatar"><svg viewBox="0 0 64 64" fill="currentColor" stroke="#fff" stroke-opacity=".55" stroke-width="1.5" aria-hidden="true"><circle cx="32" cy="18" r="13"/><path d="M9 56v-3c0-12 9-19 23-19s23 7 23 19v3a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3Z"/></svg></span><div><h3>{{detail.user.nickname}} <span class="pill" :class="detail.user.enabled?'green':'red'">● {{detail.user.enabled?'正常':'停用'}}</span></h3><p class="copy-cell">{{detail.user.phone?.replace(/^\+86/,'')}}<button type="button" class="icon-button" aria-label="复制手机号" @click="copyPhone"><span v-if="copied">✓</span><PromoterIcon v-else name="copy"/></button></p></div><div class="api-profile-actions"><button v-if="primary" type="button" class="api-portal-entry" :disabled="entering||!detail.user.enabled" @click="enter">{{entering?'进入中…':'进入 API 后台'}} ↗</button><details><summary aria-label="客户更多操作">•••</summary><div class="row-menu"><button type="button" :disabled="acting" @click="toggle">{{detail.user.enabled?'停用客户':'启用客户'}}</button></div></details></div><p class="profile-joined">加入时间：{{date(detail.user.registeredAt)}}</p></section>
<div class="api-tabs" role="tablist" aria-label="API 客户详情"><button v-for="[id,label] in tabs" :id="`api-tab-${id}`" :key="id" type="button" role="tab" :aria-selected="tab===id" :tabindex="tab===id?0:-1" aria-controls="api-detail-panel" @keydown="tabKey" @click="selectTab(id)">{{label}}</button></div>
<div id="api-detail-panel" class="api-tab-content" role="tabpanel" :aria-labelledby="`api-tab-${tab}`"><template v-if="tab==='pricing'&&!quotaHistory"><section class="api-quota"><div class="api-section-title"><h3><PromoterIcon name="card"/>额度管理</h3><button type="button" :disabled="!detail.user.keyId" @click="showQuotaHistory">额度记录 ›</button></div><div class="api-balance"><span>当前可用金额（元）</span><strong :title="detail.user.availableAmount4||undefined">¥ {{yuan(detail.user.availableAmount4)}}</strong><small>（≈ {{yuan(detail.user.availablePoints4)}} 积分）</small></div><AmountAdjustment v-if="options" reference api-client :user-id="userId" :key-id="detail.user.keyId||undefined" :options="options" :available-amount4="detail.user.availableAmount4" @changed="emit('changed')" @cancel="reload"/></section>
<section class="api-client-pricing"><div class="api-section-title"><h3><PromoterIcon name="settings"/>价格配置</h3><button v-if="primary" class="primary-action" type="button" aria-label="保存客户价格" :disabled="priceBusy||!priceReady||!pricing||priceConflict||(!pricePending&&!priceEditor?.valid)" @click="savePrices">{{priceBusy?'保存中…':pricePending?'重试原修改':'确认修改'}}</button></div><p v-if="priceError" role="alert">{{priceError}} <button v-if="!pricePending" type="button" @click="loadPrices">重新读取价格</button></p><ApiClientPrices v-if="pricing" ref="priceEditor" v-model="prices" :prices="pricing.defaults||[]" :points-per-yuan4="options?.pointsPerYuan4||''" :readonly="!primary" :disabled="priceBusy||!!pricePending||!priceReady"/></section></template>
<section v-else class="api-records"><div v-if="quotaHistory" class="api-section-title"><h3>额度记录</h3><button type="button" @click="quotaHistory=false">返回额度管理</button></div><p v-if="recordError" role="alert">{{recordError}} <button @click="loadRecords">重试</button></p><p v-else-if="recordBusy" role="status">正在读取记录…</p><template v-else>
<template v-if="quotaHistory"><table v-if="ledger.length"><thead><tr><th>时间</th><th>类型</th><th>变动积分</th><th>剩余积分</th></tr></thead><tbody><tr v-for="(row,i) in ledger.slice(offset,offset+10)" :key="i"><td>{{date(row.recordedAt)}}</td><td>{{({RECHARGE:'充值',CONSUME:'消费',REFUND:'退款',ADMIN_DEBIT:'扣减',ADMIN_ADJUST:'调整'} as Record<string,string>)[row.kind||'']||row.kind}}</td><td>{{yuan(row.points4)}}</td><td>{{yuan(row.balanceAfter4)}}</td></tr></tbody></table><p v-else class="directory-empty">暂无额度记录</p></template>
<template v-else-if="tab==='recharges'"><table v-if="recharges.length"><thead><tr><th>时间</th><th>金额（元）</th><th>来源</th><th>状态</th></tr></thead><tbody><tr v-for="row in recharges.slice(offset,offset+10)" :key="row.orderId||undefined"><td :title="row.orderId||undefined">{{date(row.createdAt)}}</td><td :title="row.amount4||undefined">{{yuan(row.amount4)}}</td><td>{{row.source==='CORPORATE'?'公户转账':row.source==='MANUAL'?'后台充值':'线上支付'}}</td><td><span class="pill" :class="row.fulfilled?'green':'neutral'">{{rechargeStatus(row)}}</span></td></tr></tbody></table><p v-else class="directory-empty">暂无充值记录</p></template>
<template v-else-if="tab==='usage'"><div class="api-usage-summary"><div><span>累计调用</span><strong>{{detail.summary?.totalCalls?.toLocaleString()??'—'}}</strong></div><div><span>累计消费（元）</span><strong>{{yuan(detail.summary?.netConsumptionAmount4)}}</strong></div></div><table v-if="usage.length"><thead><tr><th>时间</th><th>模型</th><th>消耗积分</th><th>状态</th></tr></thead><tbody><tr v-for="row in usage" :key="row.ledger?.id||undefined"><td>{{date(row.ledger?.createdAt)}}</td><td>{{row.modelName||row.ledger?.model||'—'}}</td><td>{{yuan(row.ledger?.netPoints4)}}</td><td>{{({SUCCEEDED:'成功',PARTIAL_SUCCESS:'部分成功',FAILED:'失败',RUNNING:'生成中',TIMED_OUT:'已超时'} as Record<string,string>)[row.taskStatus||'']||row.taskStatus||'—'}}</td></tr></tbody></table><p v-else class="directory-empty">暂无使用记录</p></template>
<template v-else><table v-if="logs.length"><thead><tr><th>时间</th><th>操作</th><th>操作人</th><th>备注</th></tr></thead><tbody><tr v-for="(row,i) in logs.slice(offset,offset+10)" :key="`${row.id}-${i}`"><td>{{date(row.time)}}</td><td>{{row.action}}</td><td>{{row.actor||'—'}}</td><td>{{row.remark||'—'}}</td></tr></tbody></table><p v-else class="directory-empty">暂无操作日志</p></template>
<footer v-if="recordTotal>10" class="api-record-pagination"><button type="button" :disabled="offset===0" @click="page(offset-10)">上一页</button><span>{{Math.floor(offset/10)+1}} / {{Math.ceil(recordTotal/10)}}</span><button type="button" :disabled="offset+10>=recordTotal" @click="page(offset+10)">下一页</button></footer></template></section>
</div></template></div></template>
